const { useEffect, useRef, useState } = React;

// 画布框架：按 DPR 设置像素尺寸、跟随宽度重绘、切换主题时重绘；坐标单位为 CSS 像素
const useCanvas = (draw, deps) => {
  const ref = useRef(null);
  const { color } = useTokens();
  // 重绘函数每次渲染更新，尺寸监听只建立一次，动画逐帧重绘时不重复创建观察器
  const renderRef = useRef(() => {});
  renderRef.current = () => {
    const canvas = ref.current;
    const ctx = canvas?.getContext("2d");
    if (!canvas || !ctx) return;
    const dpr = window.devicePixelRatio || 1;
    const { width, height } = canvas.getBoundingClientRect();
    const pixelWidth = Math.round(width * dpr);
    const pixelHeight = Math.round(height * dpr);
    // 重设尺寸会清空并重新分配画布，只在尺寸真正变化时才做
    if (canvas.width !== pixelWidth || canvas.height !== pixelHeight) {
      canvas.width = pixelWidth;
      canvas.height = pixelHeight;
    }
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, width, height);
    ctx.save();
    draw(ctx, { width, height, dpr, color });
    ctx.restore();
  };
  useEffect(() => renderRef.current(), [color, ...deps]);
  useEffect(() => {
    const canvas = ref.current;
    if (!canvas) return;
    const observer = new ResizeObserver(() => renderRef.current());
    observer.observe(canvas);
    return () => observer.disconnect();
  }, []);
  return ref;
};

// 画布上的标注文字：等宽字体、次要墨色
const note = (ctx, color, text, x, y, align = "left") => {
  ctx.save();
  ctx.font = `12px ${color("font-mono")}`;
  ctx.fillStyle = color("ink-3");
  ctx.textAlign = align;
  ctx.textBaseline = "middle";
  ctx.fillText(text, x, y);
  ctx.restore();
};

const KIT_STYLE = `
  @scope {
    .cb-grid {
      background-image: radial-gradient(var(--tau-line-1) 1px, transparent 1px);
      background-size: 20px 20px;
      background-position: 10px 10px;
    }
    .cb-range { accent-color: var(--tau-accent); }
  }
`;

const Stage = ({ canvasRef, height, className = "" }) => (
  <canvas
    ref={canvasRef}
    className={`cb-grid block w-full rounded-tau-md border border-line-1 ${className}`}
    style={{ height }}
  />
);

const Chip = ({ children }) => (
  <code className="rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-sm text-ink-2">{children}</code>
);

const Slider = ({ label, value, min, max, step = 1, onChange, format = value => value }) => (
  <label className="flex min-w-[220px] flex-1 items-center gap-3">
    <span className="shrink-0 font-tau-mono text-tau-sm text-ink-2">{label}</span>
    <input
      type="range"
      min={min}
      max={max}
      step={step}
      value={value}
      onChange={event => onChange(Number(event.target.value))}
      className="cb-range h-1.5 min-w-0 flex-1 cursor-pointer"
    />
    <span className="w-14 shrink-0 text-right font-tau-mono text-tau-sm text-ink-1">{format(value)}</span>
  </label>
);

const Demo = ({ children }) => (
  <div className="flex flex-col gap-3">
    <style>{KIT_STYLE}</style>
    {children}
  </div>
);

const Row = ({ children }) => <div className="flex flex-wrap items-center gap-x-6 gap-y-3">{children}</div>;

const createBalls = (width, height) =>
  Array.from({ length: 10 }, (_, index) => {
    const r = 12 + Math.random() * 22;
    return {
      x: r + Math.random() * (width - r * 2),
      y: r + Math.random() * (height - r * 2),
      r,
      token: `tag-${(index % 5) + 1}`,
      hit: false,
    };
  });

const Component = () => {
  const [balls, setBalls] = useState([]);
  const [result, setResult] = useState("点击画布中的小球");
  const sizeRef = useRef({ width: 0, height: 0 });

  const ref = useCanvas((ctx, { width, height, color }) => {
    sizeRef.current = { width, height };
    balls.forEach(ball => {
      ctx.beginPath();
      ctx.arc(ball.x, ball.y, ball.r, 0, Math.PI * 2);
      ctx.fillStyle = color(ball.hit ? "accent" : `${ball.token}-soft`);
      ctx.strokeStyle = color(ball.hit ? "accent" : ball.token);
      ctx.lineWidth = 2;
      ctx.fill();
      ctx.stroke();
    });
  }, [balls]);

  useEffect(() => {
    const { width, height } = ref.current.getBoundingClientRect();
    setBalls(createBalls(width || 480, height || 240));
  }, []);

  // isPointInPath 使用画布像素坐标，不受当前变换影响，所以要乘以 dpr
  const handleClick = event => {
    const canvas = ref.current;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    const rect = canvas.getBoundingClientRect();
    const dpr = window.devicePixelRatio || 1;
    const x = (event.clientX - rect.left) * dpr;
    const y = (event.clientY - rect.top) * dpr;
    let hitIndex = -1;
    balls.forEach((ball, index) => {
      ctx.beginPath();
      ctx.arc(ball.x, ball.y, ball.r, 0, Math.PI * 2);
      if (ctx.isPointInPath(x, y)) hitIndex = index;
    });
    setResult(hitIndex < 0 ? "未命中任何小球" : `命中第 ${hitIndex + 1} 个小球`);
    if (hitIndex >= 0) setBalls(list => list.map((ball, index) => (index === hitIndex ? { ...ball, hit: !ball.hit } : ball)));
  };

  const regenerate = () => {
    const { width, height } = sizeRef.current;
    setBalls(createBalls(width || 480, height || 240));
    setResult("点击画布中的小球");
  };

  return (
    <Demo>
      <div onClick={handleClick} className="cursor-pointer">
        <Stage canvasRef={ref} height={240} />
      </div>
      <Row>
        <span className="font-tau-mono text-tau-sm text-ink-2">{result}</span>
        <ui.Button variant="ghost" size="sm" icon={icons.Shuffle} className="ml-auto" onClick={regenerate}>
          重新生成
        </ui.Button>
      </Row>
    </Demo>
  );
};
